<!doctype html><html><head><meta charset="utf-8"><style>body{font:13px DejaVu Sans;color:#16352d}h1{margin:0;color:#087a4b}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{padding:8px;border-bottom:1px solid #d8e5df;text-align:left}th{background:#eef8f2}.right{text-align:right}.box{background:#eef8f2;padding:12px;margin:18px 0}.muted{color:#61746d}</style></head><body><h1>{{ $business->trade_name ?: $business->name }}</h1><p class="muted">{{ $business->address }} · {{ $business->mobile }} · {{ $business->email }}</p><hr><h2>Sales Invoice</h2><table><tr><td><strong>Invoice:</strong> {{ $invoice->invoice_number }}</td><td class="right"><strong>Date:</strong> {{ $invoice->invoice_date?->format('d M Y') }}</td></tr><tr><td><strong>Customer:</strong> {{ $invoice->customer->name }}</td><td class="right"><strong>Branch:</strong> {{ $invoice->branch?->name }}</td></tr></table><table><thead><tr><th>Product</th><th class="right">Qty</th><th class="right">Unit price</th><th class="right">Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->product_name }}</td><td class="right">{{ $item->quantity }}</td><td class="right">{{ number_format($item->unit_price,2) }}</td><td class="right">{{ number_format($item->line_total,2) }}</td></tr>@endforeach</tbody></table><table><tr><td class="right">Subtotal</td><td class="right">{{ number_format($invoice->subtotal,2) }}</td></tr><tr><td class="right">Discount</td><td class="right">{{ number_format($invoice->discount,2) }}</td></tr><tr><td class="right">VAT</td><td class="right">{{ number_format($invoice->vat,2) }}</td></tr><tr><td class="right"><strong>Grand total</strong></td><td class="right"><strong>BDT {{ number_format($invoice->grand_total,2) }}</strong></td></tr><tr><td class="right">Paid</td><td class="right">{{ number_format($invoice->paid_amount,2) }}</td></tr></table><div class="box"><strong>Payment status:</strong> {{ ucfirst($invoice->payment_status) }} · Thank you for your business.</div></body></html>
